INSERT INTO `products` VALUES (1,'010725BAXKPI6','Áo thun nam cổ tròn',200000.00,'Chất liệ','products/9nxC9UTzbsOR2ny3FA2uERkMrlPSceOuWsbClSWJ.webp','out_of_stock',3,22,'2025-07-01 08:56:44','2025-08-04 04:34:00',NULL,11,8,NULL,NULL),(2,'020725BAK5WBQ','Balo infinity',399000.00,'dây kéo phản quan',NULL,'active',3,22,'2025-07-02 10:07:41','2025-07-15 02:54:38',NULL,350,20,'đen',NULL),(3,'030725MTYNX5N','Máy tính Casio Fx-580VNX',725000.00,'Máy tính Casio fx-580VN X thuộc dòng máy tính khoa học ClassWiz của hãng máy tính CASIO. Máy được trang bị màn hình LCD có độ phân giải cao. Casio fx-580VN X là bước tiến đột phá, mang công nghệ đến gần hơn với lớp học. Độ phân giải của màn hình của Casio fx-580VN X được tăng gấp 4 lần, hỗ trợ tăng lượng thông tin hiển thị cũng như cải thiện tính tiện dụng của sản phẩm. Đây là chiếc máy tính khoa học có hiệu suất cao, tốc độ tính toán nhanh; phù hợp với nhiều cấp học từ học sinh,',NULL,'active',4,22,'2025-07-03 01:33:17','2025-07-05 16:23:23',NULL,50,20,NULL,NULL),(4,'030725MTIY5M5','Máy tính Casio Fx-570VN Plus New ( 2nd Edition)',565000.00,'Máy tính Casio FX 570VN PLUS 2nd Edition được ra mắt vào tháng 9 năm 2019.',NULL,'out_of_stock',1,22,'2025-07-03 01:36:07','2025-07-05 08:53:17',NULL,0,20,NULL,NULL),(5,'030725MT0NGE8','Máy tính Casio Fx-880BTG',720000.00,'Máy tính Casio fx-880BTG thuộc dòng máy tính khoa học ClassWiz của hãng máy tính CASIO. Máy tính Casio fx-880BTG đã ra đời với nhiều cải tiến về: thiết kế - giao diện, tính năng nổi trội và độ chính xác cao… để đáp ứng thực tiễn dạy và học tại Việt Nam, đồng thời thay đổi tư duy học tập lâu nay của học sinh.',NULL,'active',1,22,'2025-07-03 01:38:31','2025-07-05 16:21:24',NULL,130,20,NULL,NULL),(6,'030725MTEXCW1','Máy tính Casio MX-12B',158400.00,'Máy Tính Để Bàn Casio MX-12B sẽ là công cụ tính toán hoàn hảo trong công việc hằng ngày của bạn. Máy được thiết kế cứng cáp, bền đẹp bằng chất liệu nhựa cao cấp. Máy được tích hợp nhiều chức năng hiện đại. giúp bạn hoàn thành công việc một cách nhanh chóng. Màn hình máy rộng, hiển thị rõ nét, giúp bạn xem kết quả và dữ liệu một cách dễ dàng',NULL,'active',1,22,'2025-07-03 01:40:13','2025-07-05 16:24:57',NULL,175,10,NULL,NULL),(7,'030725DHPLB15','Đồng hồ Casio MSG-S500CG-1ADR',9048000.00,NULL,NULL,'active',6,22,'2025-07-03 01:52:28','2025-07-05 16:25:10',NULL,188,50,NULL,NULL),(8,'030725DHM61IU','Đồng hồ Casio MSG-S500CD-7ADR',7403000.00,'Cùng chiêm ngưỡng những mẫu đồng hồ mới đầy ấn tượng với thiết kế đơn giản và thanh lịch của BABY-G G-MS, dòng sản phẩm dành cho những người phụ nữ hiện đại năng động và sành điệu.Phần viền mỏng và sắc nét, vạch chỉ giờ hình tam giác, nút điều chỉnh bát giác cùng nhiều chi tiết khác, tất cả đã tạo nên một kiệt tác hiện đại không thể cưỡng lại. Dây đeo được làm từ chất liệu kim loại và nhựa composite mới.Mẫu đồng hồ sở hữu thiết kế vỏ mỏng phù hợp với mọi hoàn cảnh, ba kim chỉ thời gian và hiển thị ngày, hoạt động bằng năng lượng mặt trời và khả năng chống nước tới 100m.Mẫu G-MS mới này chắc chắn là sự lựa chọn hoàn hảo cho công việc, giải trí hay bất cứ hoạt động nào khác của bạn.',NULL,'active',6,22,'2025-07-03 01:55:55','2025-07-03 01:55:55',NULL,268,50,NULL,NULL),(9,'040725DHT8YPL','Đồng hồ Casio MSG-400G-1A2DRDAS',2312321312.00,'DD','products/0qaOfQH0Afk6zsTIeIOEZCLSAcJ4CP1h6WuywDcG.jpg','active',6,22,'2025-07-04 03:34:08','2025-07-21 02:40:21',NULL,123,20,'Hồng',NULL),(10,'040725MTWO0QZ','Máy Tính Casio WD-220MS',50000000.00,'đẹp','products/RztoCVrZJQ95kYuXvT7HQ866O2Btysmnp3iBCmZr.jpg','active',1,22,'2025-07-04 07:44:14','2025-07-20 14:37:04',NULL,60,10,NULL,NULL),(11,'040725MTJTYUH','máy tính cũ',3000000.00,'dd','products/Q7tFx1vvPGHHNKglZCkF80uAzmMe7NULcHJfIAvI.png','active',4,22,'2025-07-04 08:15:02','2025-07-15 03:55:32',NULL,81,7,NULL,NULL),(12,'040725MT4GWMD','Máy tính Casio HL-815L',30000.00,'rất rẻ','products/dSIwlMPePk00P05sFFKVvmSve3rvr4EGLV7Cp4WW.jpg','active',1,22,'2025-07-04 08:21:48','2025-08-04 04:36:34',NULL,19,10,NULL,NULL),(13,'040725MT9